def read_json_noatime(path):
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NOATIME)
    try:
        data=b''
        while part:=os.read(fd,MIB):
            data+=part;assert len(data)<=4*MIB
    finally:os.close(fd)
    return json.loads(data)


